'use strict';
const $ = (id) => document.getElementById(id);
const escapeHTML = (value) => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const state = {view:'welcome',step:0,workspace:'new',role:'controller',paired:false,environment:'venv',tailnet:'existing',selected:null,inspector:'variables',transform:0,zoom:1,pan:{x:0,y:0},radial:false,running:false,variables:{},completed:new Set(),filter:'All',alias:false,collapsed:{}};
const titles = {welcome:'Overview',setup:'Connect a device',lab:'Notebook → graph',atlas:'Interface atlas'};
let toastTimer, animationFrame, runTimer;
function toast(message){ $('toast').textContent=message; $('toast').classList.add('show'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3600); }
function switchView(view){if(!titles[view])return;state.view=view;document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id==='view-'+view));document.querySelectorAll('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('page-name').textContent=titles[view];location.hash=view;if(view==='lab'){requestAnimationFrame(()=>{setTransform(state.transform);defaultCanvasView();});}window.scrollTo({top:0,behavior:'instant'});}
document.addEventListener('click',event=>{const target=event.target.closest('[data-view]');if(target)switchView(target.dataset.view);});
document.querySelector('.brand').addEventListener('click',()=>switchView('welcome'));
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(view!==state.view&&titles[view])switchView(view);});
function dialog(title,body,eyebrow='DESIGN DETAIL'){$('dialog-eyebrow').textContent=eyebrow;$('dialog-content').innerHTML='<h2>'+title+'</h2>'+body;$('detail-dialog').showModal();}
$('close-dialog').onclick=()=>$('detail-dialog').close();
$('detail-dialog').addEventListener('click',e=>{if(e.target===$('detail-dialog'))$('detail-dialog').close();});
const command = (code,id,output='') => `<div class="command-cell"><div class="command-meta"><span>⌘ MAC CONTROLLER · ${state.paired?'SIMULATED PAIRING':'NOT CONNECTED'}</span><button class="text-button" data-copy="${escapeHTML(code)}">Copy command</button></div><pre>${escapeHTML(code)}</pre>${output?`<div class="command-output">${escapeHTML(output)}</div>`:''}</div>`;
const stepNames=['Workspace','Device identity','Permissions','Python environment','Runtime & network','Ready to open'];
function renderSetup(){
 $('setup-steps').innerHTML=stepNames.map((n,i)=>`<li><button class="${i===state.step?'active':i<state.step?'complete':''}" data-step="${i}"><b>${i<state.step?'✓':i+1}</b>${n}</button></li>`).join('');
 const content=[
  `<h2>Choose your workspace</h2><p>Keep experiments, graph documents, and outputs together. Existing workspaces restore their settings after the companion validates them.</p><div class="choice-row"><button class="choice-card ${state.workspace==='new'?'selected':''}" data-workspace="new"><b>＋ First visit</b><span>Create a MainAIger workspace</span></button><button class="choice-card ${state.workspace==='existing'?'selected':''}" data-workspace="existing"><b>↳ Return to my work</b><span>Open an existing workspace</span></button></div><label class="field-label" for="workspace-path">Workspace directory — example path</label><div class="field-row"><input class="text-field" id="workspace-path" value="~/mainaiger"><button class="button" id="browse-directory">Choose…</button></div><div class="path-preview">mainaiger/<br>  main/<br>    online_exp/<br>      signal-experiment.ipymb<br>  environments/  logs/  artifacts/</div><div class="inline-note">The website cannot create native folders automatically. The installed companion will confirm this path and create it on your selected device.</div>`,
  `<h2>Know where code will run</h2><p>Device names are convenient labels. A stable device ID identifies the machine even when its address changes.</p><div class="choice-row"><button class="choice-card ${state.role==='controller'?'selected':''}" data-role="controller"><b>◉ Controller + worker</b><span>This laptop controls and executes work</span></button><button class="choice-card ${state.role==='worker'?'selected':''}" data-role="worker"><b>◈ Worker server</b><span>Run jobs here; control from another device</span></button></div><label class="field-label" for="device-name">Friendly name</label><input class="text-field" id="device-name" value="Mac controller"><div class="metric-grid"><div class="metric-tile"><b>Unknown</b><span>CPU · detected after pairing</span></div><div class="metric-tile"><b>Unknown</b><span>Memory · after pairing</span></div><div class="metric-tile"><b>Unknown</b><span>Disk space · after pairing</span></div></div><div class="permission-row"><span>Device ID<br><small>Assigned by companion on installation</small></span><span class="tag neutral">Not connected</span></div><label class="field-label" for="host-address">Optional private host address</label><input class="text-field" id="host-address" placeholder="nexus.your-tailnet.ts.net"><div class="field-row"><div style="flex:1"><label class="field-label" for="device-username">OS / SSH username</label><input class="text-field" id="device-username" placeholder="your-username"></div><div style="flex:1"><label class="field-label" for="ssh-nickname">SSH nickname</label><input class="text-field" id="ssh-nickname" placeholder="mainaiger-nexus"></div></div>`,
  `<h2>Make access explicit</h2><p>A permission card states what MainAIger may request on this device. Native Python remains trusted local code until OS isolation is implemented.</p><label class="permission-row"><input type="checkbox" checked><span>Experiment directory<small>~/mainaiger/main/online_exp</small></span><select aria-label="Experiment directory access"><option>Read + write</option><option>Read only</option></select></label><label class="permission-row"><input type="checkbox"><span>Additional dataset folder<small>Choose a folder during native setup</small></span><select aria-label="Dataset directory access"><option>Read only</option><option>Read + write</option></select></label><label class="permission-row"><input type="checkbox"><span>Terminal commands<small>Show command, device, directory, and privilege before execution</small></span></label><label class="permission-row"><input type="checkbox"><span>Remote access<small>Pair a controller with a private worker</small></span></label><div class="inline-note"><b>Trusted local Python mode.</b> A virtual environment and folder list are not an operating-system sandbox. Arbitrary Python can access files available to its OS account.</div>`,
  `<h2>A visible Python environment</h2><p>Reuse an environment or create one. Each kernel shows its interpreter, package inventory, and owning device.</p><div class="choice-row"><button class="choice-card ${state.environment==='venv'?'selected':''}" data-environment="venv"><b>Python venv</b><span>Small default for a first install</span></button><button class="choice-card ${state.environment==='conda'?'selected':''}" data-environment="conda"><b>Existing conda</b><span>Select and validate an existing environment</span></button></div>${command(state.environment==='venv'?'python3 -m venv ~/mainaiger/environments/lab':'conda env list','environment')}<div class="permission-row"><span class="mock-state gray"></span><span>Environment status<small>Not checked — companion required</small></span><button class="small-button" id="preview-env">Preview validation</button></div><p>No command above runs in this page. In the installed setup notebook, Run becomes available after pairing and command review.</p>`,
  `<h2>Keep the work running</h2><p>A service owns runtime lifetime. tmux is an optional way to inspect terminal sessions; it is separate from a Python kernel.</p><div class="process-strip"><div><small>HOST SERVICE</small><b>MainAIger</b><small>Persistent supervisor</small></div><div><small>PYTHON PROCESS</small><b>Lab kernel</b><small>Independent namespace</small></div><div><small>OPTIONAL TERMINAL</small><b>tmux session</b><small>Visible terminal workspace</small></div></div><label class="field-label" for="tailnet-choice">Private network plan</label><select class="text-field" id="tailnet-choice"><option value="existing" ${state.tailnet==='existing'?'selected':''}>Use my existing Tailscale tailnet</option><option value="new" ${state.tailnet==='new'?'selected':''}>Set up a new Tailscale account / tailnet</option><option value="none" ${state.tailnet==='none'?'selected':''}>Local device only for now</option></select>${command('tailscale status\n# Optional terminal inspection:\ntmux list-sessions','runtime')}<button class="button" id="preview-pair">${state.paired?'✓ Simulated pairing complete':'Preview companion pairing'}</button><div class="inline-note">A tailnet is a private device network. Subnet routing is optional and is not needed just to connect this laptop and Nexus.</div>`,
  `<h2>Ready for the design walkthrough</h2><p>The configuration below is a preview. A real setup finishes only after companion, environment, workspace, and runtime checks pass.</p><ul class="checklist"><li>Workspace: ${state.workspace==='new'?'create':'reopen'} ~/mainaiger</li><li>Device role: ${state.role==='controller'?'controller + worker':'worker server'}</li><li>Environment: ${state.environment==='venv'?'Python venv':'existing conda'}</li><li>Network: ${state.tailnet==='none'?'local only':state.tailnet==='new'?'new tailnet':'existing tailnet'}</li><li>Runtime: simulated in this preview</li></ul><div class="command-cell"><div class="command-meta"><span>INSTALLED EXPERIENCE — PLANNED</span></div><div class="command-output">Verify workspace → verify interpreter → start service\nOpen private MainAIger Lab URL in a new browser tab</div></div><button class="button primary" data-view="lab">Open the canvas preview ↗</button>`
 ];
 $('setup-content').innerHTML=content[state.step];$('step-count').textContent=`${state.step+1} / ${stepNames.length}`;$('setup-back').disabled=state.step===0;$('setup-next').textContent=state.step===5?'Open canvas →':'Continue →';
}
$('setup-back').onclick=()=>{state.step=Math.max(0,state.step-1);renderSetup();};
$('setup-next').onclick=()=>{if(state.step===5)switchView('lab');else{state.step++;renderSetup();}};
document.addEventListener('click',event=>{
 const el=event.target.closest('[data-step],[data-workspace],[data-role],[data-environment],[data-copy]');if(!el)return;
 if(el.dataset.step!==undefined){state.step=Number(el.dataset.step);renderSetup();}
 for(const name of ['workspace','role','environment'])if(el.dataset[name]){state[name]=el.dataset[name];renderSetup();}
 if(el.dataset.copy)copyText(el.dataset.copy);
});
$('setup-content').addEventListener('change',e=>{if(e.target.id==='tailnet-choice')state.tailnet=e.target.value;});
$('setup-content').addEventListener('click',e=>{
 if(e.target.id==='browse-directory')dialog('Workspace selection','<p>The native companion opens the operating-system folder chooser and checks read/write access. The web demo offers import/export without promising unrestricted filesystem access.</p><div class="path-preview">Example selection: ~/mainaiger<br>Status: preview only — no directory created</div>');
 if(e.target.id==='preview-env')dialog('Environment validation','<p>Example of the check result after installation. These values are illustrative.</p><ul class="checklist"><li>Python executable resolves</li><li>Environment is separate from system Python</li><li>Jupyter kernel starts and reports a heartbeat</li><li>Package inventory recorded</li></ul><span class="pill amber">Simulated results</span>');
 if(e.target.id==='preview-pair')dialog('Pair this device','<p>The installed companion displays a short-lived pairing challenge. The user approves the requesting controller locally.</p><div class="path-preview">Example code: M-A-I-N<br>Controller: Mac controller<br>Scope: one workspace</div><button class="button primary" id="complete-pair">Simulate local approval</button>','PAIRING DESIGN');
});
document.addEventListener('click',e=>{if(e.target.id==='complete-pair'){state.paired=true;$('detail-dialog').close();renderSetup();toast('Pairing simulated. No device connection was made.');}});
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Command copied. Review it before running on your device.');}catch{dialog('Copy command',`<p>Select and copy this text.</p><pre>${escapeHTML(text)}</pre>`);}}
const nodes=[
 {id:'intent',kind:'markdown',title:'Intent · from signal to result',text:'Load a signal, normalize its amplitude, estimate a model, and inspect the result. Keep the code and output beside each step.'},
 {id:'start',kind:'trigger',title:'▶ Start'},
 {id:'load',kind:'code',title:'Load a signal',code:'import numpy as np\nx = np.linspace(0, 1, 1024)\nsignal = np.sin(2 * np.pi * 8 * x)',output:'signal: ndarray · shape (1024,) · float64',variables:{x:['ndarray','(1024,)'],signal:['ndarray','(1024,)']},requires:[]},
 {id:'normalize',kind:'code',title:'Normalize amplitude',code:'scale = np.max(np.abs(signal))\nfeatures = signal / max(scale, 1e-12)',output:'features: ndarray · range [−1.00, 1.00]',variables:{features:['ndarray','(1024,)']},requires:['signal']},
 {id:'train',kind:'code',title:'Estimate a model',code:'model = {"rms": float(\n    np.sqrt(np.mean(features ** 2))\n)}',output:'model: dict · rms = 0.7068',variables:{model:['dict','1 key']},requires:['features']},
 {id:'inspect',kind:'code',title:'Inspect the signal',code:'preview = features[:8]\nprint(preview.round(3))',output:'[0.000 0.049 0.098 0.147 0.195 …]',variables:{preview:['ndarray','(8,)']},requires:['features']},
 {id:'evaluate',kind:'code',title:'Evaluate result',code:'result = {"rms": model["rms"],\n          "samples": len(features)}\nprint(result)',output:'{rms: 0.7068, samples: 1024}',variables:{result:['dict','2 keys']},requires:['model','features']},
 {id:'finish',kind:'trigger finish',title:'■ Finish'}
];
const graphPositions={intent:[65,55],start:[470,65],load:[360,150],normalize:[360,335],train:[130,535],inspect:[590,535],evaluate:[130,735],finish:[472,965]};
const edges=[['start','load','control'],['load','normalize','control'],['normalize','train','control'],['normalize','inspect','control'],['train','evaluate','control'],['evaluate','finish','control'],['inspect','finish','control'],['load','normalize','data','signal'],['normalize','train','data','features'],['normalize','inspect','data','features'],['train','evaluate','data','model']];
let positions={},manualPositions={};
try{const saved=JSON.parse(localStorage.getItem('mainaiger-design-layout')||'null');if(saved&&typeof saved==='object')manualPositions=saved;}catch{}
function renderNodes(){
 $('nodes-layer').innerHTML=nodes.map((n,i)=>`<article class="node ${n.kind} ${state.selected===n.id?'selected':''} ${state.completed.has(n.id)?'completed':''}" data-node="${n.id}" tabindex="0" aria-label="${escapeHTML(n.title)}"><span class="port input"></span><div class="node-head"><span class="node-number">${n.kind==='code'?'['+(state.completed.has(n.id)?i-1:' ')+']':''}</span>${n.kind==='code'?`<button class="node-run" data-run-node="${n.id}" aria-label="Run ${n.title} in simulation">▶</button>`:''}<b>${n.title}</b>${n.kind==='code'?'<span class="node-kind">PYTHON</span>':''}</div>${n.kind==='markdown'?`<div class="markdown-text">${n.text}</div>`:n.kind==='code'?`<div class="node-code ${state.collapsed[n.id+'-code']?'hidden':''}"><button class="code-toggle" data-collapse="${n.id}-code">${state.collapsed[n.id+'-code']?'Show code':'−'}</button><pre>${escapeHTML(n.code)}</pre></div><div class="node-output ${state.collapsed[n.id+'-output']?'hidden':''}"><button data-collapse="${n.id}-output">${state.collapsed[n.id+'-output']?'Show output':'−'}</button><span class="output-content">${state.completed.has(n.id)?n.output:'Output preview · '+n.output}</span></div><span class="port output"></span><span class="port data"></span>`:''}</article>`).join('');
 if(state.alias){const alias=document.createElement('button');alias.className='demo-alias';alias.textContent='▶ Start · alias';alias.style.cssText='left:800px;top:80px;pointer-events:auto';alias.onclick=()=>runAll();$('nodes-layer').append(alias);}
 setTransform(state.transform);
}
function notebookPosition(n,i){let y=60;for(let j=0;j<i;j++)y+=nodes[j].kind==='markdown'?125:nodes[j].kind.includes('trigger')?75:190;return[n.kind.includes('trigger')?230:115,y];}
function circularPosition(n,i){if(n.id==='intent')return[30,50];if(n.id==='start')return[535,270];if(n.id==='finish')return[535,740];const order=['load','normalize','train','inspect','evaluate'];const angle=(order.indexOf(n.id)/5)*Math.PI*2-Math.PI/2;return[420+Math.cos(angle)*350,465+Math.sin(angle)*340];}
function setTransform(value){
 state.transform=Math.max(0,Math.min(100,Number(value)));const t=state.transform/100;
 nodes.forEach((n,i)=>{const p=notebookPosition(n,i),q=manualPositions[n.id]||(state.radial?circularPosition(n,i):graphPositions[n.id]);const x=p[0]+(q[0]-p[0])*t,y=p[1]+(q[1]-p[1])*t;positions[n.id]=[x,y];const el=document.querySelector(`[data-node="${n.id}"]`);el.style.left=x+'px';el.style.top=y+'px';el.style.width=n.kind.includes('trigger')?'105px':`${330+(n.id==='intent'?-70:0)*t}px`;el.querySelectorAll('.port').forEach(port=>port.style.opacity=t);});
 $('transform-slider').value=String(value);$('notebook-mode').classList.toggle('active',value<50);$('graph-mode').classList.toggle('active',value>=50);$('edge-layer').style.opacity=Math.min(1,t*2);$('canvas-caption').textContent=value<10?'Notebook view · familiar cells, outputs, and execution counts':value<95?'Same cells unfolding · position changes, code stays intact':'Graph view · drag cells, inspect data, and follow execution';drawEdges();applyViewport();
}
function drawEdges(){
 const paths=edges.map(([from,to,type,label])=>{const a=document.querySelector(`[data-node="${from}"]`),b=document.querySelector(`[data-node="${to}"]`),pa=positions[from],pb=positions[to];if(!a||!b)return'';const data=type==='data';const x1=pa[0]+(data?a.offsetWidth:a.offsetWidth/2),y1=pa[1]+(data?a.offsetHeight/2:a.offsetHeight),x2=pb[0]+(data?b.offsetWidth:b.offsetWidth/2),y2=pb[1]+(data?b.offsetHeight/2:0);const d=data?`M ${x1} ${y1} C ${Math.max(x1,x2)+65} ${y1}, ${Math.max(x1,x2)+65} ${y2}, ${x2} ${y2}`:`M ${x1} ${y1} C ${x1} ${y1+50}, ${x2} ${y2-50}, ${x2} ${y2}`;return`<path d="${d}" fill="none" stroke="${data?'#64a1ba':'#8ca79b'}" stroke-width="${data?1.3:1.6}" ${data?'stroke-dasharray="4 5"':''} marker-end="url(#${data?'data-arrow':'arrow'})"/>${data?`<text x="${Math.max(x1,x2)+22}" y="${(y1+y2)/2}" font-family="monospace" font-size="8" fill="#6e9cae">${label}</text>`:''}`;});
 $('edge-layer').innerHTML='<defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M 0 0 L 10 5 L 0 10 z" fill="#8ca79b"/></marker><marker id="data-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto"><path d="M 0 0 L 10 5 L 0 10 z" fill="#64a1ba"/></marker></defs>'+paths.join('');
}
function applyViewport(){$('canvas-world').style.transform=`translate(${state.pan.x}px,${state.pan.y}px) scale(${state.zoom})`;$('zoom-label').textContent=Math.round(state.zoom*100)+'%';}
function fitCanvas(){const box=$('canvas-viewport').getBoundingClientRect();if(!box.width)return;if(state.transform<5){state.zoom=Math.min(1,(box.width-40)/530);state.pan={x:(box.width-550*state.zoom)/2,y:0};}else{const bounds=nodes.reduce((b,n)=>{const p=positions[n.id],el=document.querySelector(`[data-node="${n.id}"]`);return {left:Math.min(b.left,p[0]),top:Math.min(b.top,p[1]),right:Math.max(b.right,p[0]+el.offsetWidth),bottom:Math.max(b.bottom,p[1]+el.offsetHeight)};},{left:Infinity,top:Infinity,right:0,bottom:0});state.zoom=Math.max(.22,Math.min(1,(box.width-55)/(bounds.right-bounds.left),(box.height-105)/(bounds.bottom-bounds.top)));state.pan={x:(box.width-(bounds.right-bounds.left)*state.zoom)/2-bounds.left*state.zoom,y:55-bounds.top*state.zoom};}applyViewport();}
function defaultCanvasView(){
 if(state.transform<5){fitCanvas();return;}
 const box=$('canvas-viewport').getBoundingClientRect();
 const focus=positions.load||[360,150];
 state.zoom=box.width<360?.8:.95;
 state.pan={x:box.width/2-(focus[0]+165)*state.zoom,y:42};
 applyViewport();
}
function animateTransform(){cancelAnimationFrame(animationFrame);const from=state.transform,to=from>90?0:100;const begin=performance.now(),duration=window.matchMedia('(prefers-reduced-motion: reduce)').matches?1:1700;function frame(now){const t=Math.min(1,(now-begin)/duration),ease=t*t*(3-2*t);setTransform(from+(to-from)*ease);if(t<1){animationFrame=requestAnimationFrame(frame);}else{defaultCanvasView();toast(to===100?'The same cells now form a graph. Drag a header to rearrange.':'Notebook view restored. Code and outputs stayed attached.');}}animationFrame=requestAnimationFrame(frame);}
$('play-transform').onclick=animateTransform;$('transform-slider').oninput=e=>{cancelAnimationFrame(animationFrame);setTransform(e.target.value);};$('transform-slider').onchange=defaultCanvasView;
$('notebook-mode').onclick=()=>{cancelAnimationFrame(animationFrame);setTransform(0);fitCanvas();};$('graph-mode').onclick=()=>{cancelAnimationFrame(animationFrame);setTransform(100);defaultCanvasView();};
$('zoom-out').onclick=()=>{state.zoom=Math.max(.2,state.zoom/1.2);applyViewport();};$('zoom-in').onclick=()=>{state.zoom=Math.min(2,state.zoom*1.2);applyViewport();};$('fit-canvas').onclick=fitCanvas;
$('arrange-canvas').onclick=()=>{manualPositions={};persistLayout();setTransform(100);defaultCanvasView();toast('Cells arranged by execution flow.');};
$('layout-direction').onclick=()=>{state.radial=!state.radial;manualPositions={};$('layout-direction').textContent=state.radial?'Radial ◉':'Top ↓';setTransform(100);defaultCanvasView();};
$('toggle-files').onclick=()=>{$('view-lab').classList.toggle('file-collapsed');$('toggle-files').textContent=$('view-lab').classList.contains('file-collapsed')?'›':'‹';defaultCanvasView();};
let drag=null;
$('canvas-viewport').addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;const node=e.target.closest('[data-node]');if(node){selectNode(node.dataset.node);if(state.transform<95||!e.target.closest('.node-head'))return;drag={type:'node',id:node.dataset.node,x:e.clientX,y:e.clientY,start:[...positions[node.dataset.node]]};}else drag={type:'pan',x:e.clientX,y:e.clientY,start:{...state.pan}};e.currentTarget.setPointerCapture(e.pointerId);});
$('canvas-viewport').addEventListener('pointermove',e=>{if(!drag)return;if(drag.type==='node'){manualPositions[drag.id]=[Math.max(0,drag.start[0]+(e.clientX-drag.x)/state.zoom),Math.max(0,drag.start[1]+(e.clientY-drag.y)/state.zoom)];setTransform(100);}else{state.pan={x:drag.start.x+e.clientX-drag.x,y:drag.start.y+e.clientY-drag.y};applyViewport();}});
$('canvas-viewport').addEventListener('pointerup',()=>{if(drag?.type==='node')persistLayout();drag=null;});
$('canvas-viewport').addEventListener('pointercancel',()=>{drag=null;});
$('canvas-viewport').addEventListener('wheel',e=>{e.preventDefault();if(e.ctrlKey||e.metaKey){state.zoom=Math.max(.2,Math.min(2,state.zoom*(e.deltaY<0?1.06:.94)));}else{state.pan.y-=e.deltaY;state.pan.x-=e.deltaX;}applyViewport();},{passive:false});
function persistLayout(){try{localStorage.setItem('mainaiger-design-layout',JSON.stringify(manualPositions));$('saved-mark').textContent='Layout saved in this browser';}catch{$('saved-mark').textContent='Layout in session memory';}}
document.addEventListener('click',e=>{const collapse=e.target.closest('[data-collapse]');if(collapse){state.collapsed[collapse.dataset.collapse]=!state.collapsed[collapse.dataset.collapse];renderNodes();return;}const run=e.target.closest('[data-run-node]');if(run){e.stopPropagation();runNode(run.dataset.runNode);return;}});
$('nodes-layer').addEventListener('keydown',e=>{const el=e.target.closest('[data-node]');if(!el)return;if(e.key==='Enter'){selectNode(el.dataset.node);e.preventDefault();}if(e.shiftKey&&e.key==='Enter'){runNode(el.dataset.node);e.preventDefault();}});
function selectNode(id){state.selected=id;document.querySelectorAll('[data-node]').forEach(el=>el.classList.toggle('selected',el.dataset.node===id));$('selection-status').textContent='Selected: '+nodes.find(n=>n.id===id).title;renderInspector();}
function runNode(id,quiet=false){const n=nodes.find(n=>n.id===id);if(!n)return false;selectNode(id);if(n.kind!=='code'){if(id==='start')runAll();else if(id==='finish')toast('Finish completes this run. The Python kernel stays available.');else toast('Intent cells describe the workflow and do not execute.');return true;}const missing=n.requires.filter(v=>!state.variables[v]);if(missing.length){state.inspector='variables';renderInspector(missing);$('run-status').innerHTML='<span class="dot amber"></span> Blocked · missing '+escapeHTML(missing.join(', '));if(!quiet){if(window.innerWidth<580){const producer=nodes.find(p=>p.variables?.[missing[0]]);dialog('Missing input: '+escapeHTML(missing.join(', ')), '<p>This cell needs a value produced by '+escapeHTML(producer?.title||'an external input')+'. Run its prerequisite first.</p>'+ (producer?'<button class="button primary" data-run-node="'+producer.id+'">Simulate producer</button>':''));}else toast('Missing '+missing.join(', ')+'. Inspect the producer in the right panel.');}return false;}Object.assign(state.variables,n.variables);state.completed.add(id);renderNodes();renderInspector();$('run-status').innerHTML='<span class="dot"></span> Demo completed · '+n.title;if(!quiet)toast(n.title+' simulated. No Python was executed.');return true;}
function runAll(){if(state.running)return;state.running=true;state.variables={};state.completed.clear();const queue=['load','normalize','train','inspect','evaluate'];let index=0;$('run-all').textContent='◌ Running demo';function next(){if(!state.running)return;if(index>=queue.length){state.running=false;$('run-all').textContent='▶ Run demo';$('run-status').innerHTML='<span class="dot"></span> Demo finished · kernel would remain idle';renderInspector();return;}const id=queue[index++];runNode(id,true);document.querySelector(`[data-node="${id}"]`)?.classList.add('running');runTimer=setTimeout(next,550);}next();}
$('run-all').onclick=runAll;$('run-selected').onclick=()=>state.selected?runNode(state.selected):toast('Select a code cell first, then choose Run selected.');
$('reset-demo').onclick=()=>{clearTimeout(runTimer);state.running=false;state.variables={};state.completed.clear();state.selected=null;$('run-all').textContent='▶ Run demo';$('run-status').innerHTML='<span class="dot gray"></span> Demo idle';$('selection-status').textContent='Select a cell to inspect it';renderNodes();renderInspector();toast('Simulated memory and run state reset.');};
function renderInspector(missing=[]){
 document.querySelectorAll('[data-inspector]').forEach(el=>el.classList.toggle('active',el.dataset.inspector===state.inspector));
 if(state.inspector==='processes'){$('inspector-content').innerHTML=`<div class="inspector-block"><h3><span class="dot"></span> Example kernel</h3><span class="state-badge">Simulated ${state.running?'running':'idle'}</span><div class="inspect-row"><span>Device</span><b>Mac controller</b></div><div class="inspect-row"><span>Environment</span><span>lab / Python</span></div><div class="inspect-row"><span>Runtime ID</span><span>demo-kernel-01</span></div><div class="inspect-row"><span>CPU · sample</span><b>${state.running?'28':'0'}%</b></div><div class="meter"><i style="width:${state.running?'28':'0'}%"></i></div><div class="inspect-row"><span>RSS · sample</span><b>182 MB</b></div><div class="meter"><i style="width:18%"></i></div><button class="small-button" id="interrupt-demo">Interrupt demo</button><button class="small-button" id="kernel-detail">Lifecycle</button><p>Metrics are example values, not measurements from your device.</p></div><div class="inspector-block"><h3>Live sessions</h3><div class="inspect-row"><span>Notebook run</span><span>${state.running?'Running':'Idle'}</span></div><div class="inspect-row"><span>API service</span><span>Example</span></div><button class="small-button" id="open-process">Open process tab</button><button class="small-button" id="history-detail">Run history</button></div>`;return;}
 const rows=Object.entries(state.variables);const n=nodes.find(n=>n.id===state.selected);
 $('inspector-content').innerHTML=`<div class="inspector-block"><h3>Kernel namespace <span class="tag neutral">Demo</span></h3>${rows.length?`<table class="variable-table"><thead><tr><th>Name</th><th>Type</th><th>Shape</th></tr></thead><tbody>${rows.map(([k,v])=>`<tr><td>${k}</td><td>${v[0]}</td><td>${v[1]}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state"><span>◫</span><p>No simulated variables yet.<br>Run a cell to populate this panel.</p></div>'}<p>Each real runtime has its own namespace. Cross-process values require explicit transfer.</p></div>${n?`<div class="inspector-block"><h3>${n.title}</h3><div class="inspect-row"><span>Device</span><b>Mac controller</b></div><div class="inspect-row"><span>Inputs</span><span>${n.requires?.join(', ')||'None'}</span></div><div class="inspect-row"><span>State</span><span>${state.completed.has(n.id)?'Demo completed':'Not run'}</span></div>${missing.length?`<div class="missing-card"><b>Missing: ${missing.join(', ')}</b><p>Producer: ${nodes.find(p=>p.variables?.[missing[0]])?.title||'External input'}</p><button class="small-button" data-jump="${nodes.find(p=>p.variables?.[missing[0]])?.id}">Jump to producer ↗</button><button class="small-button" id="run-prerequisites">Run prerequisites</button></div>`:''}<button class="small-button" id="inspect-contract">Inspect contract</button></div>`:'<div class="inspector-block"><h3>Inspect a cell</h3><p>Select any cell to see its inputs, device, execution state, and missing data.</p><button class="small-button" data-jump="train" data-try-missing="true">Try a missing dependency ↗</button></div>'}`;
}
document.querySelectorAll('[data-inspector]').forEach(el=>el.onclick=()=>{state.inspector=el.dataset.inspector;renderInspector();});
$('inspector-content').addEventListener('click',e=>{const jump=e.target.closest('[data-jump]');if(jump){const id=jump.dataset.jump;if(!positions[id])return;selectNode(id);const box=$('canvas-viewport').getBoundingClientRect();state.zoom=.9;state.pan={x:box.width/2-(positions[id][0]+165)*state.zoom,y:100-positions[id][1]*state.zoom};applyViewport();if(jump.dataset.tryMissing)runNode(id);return;}if(e.target.id==='run-prerequisites'){const selected=state.selected;const queue=['load','normalize','train','inspect','evaluate'];for(const id of queue){if(id===selected)break;runNode(id,true);}selectNode(selected);toast('Prerequisite cells simulated. The selected cell is now ready.');}if(e.target.id==='interrupt-demo'){clearTimeout(runTimer);state.running=false;$('run-all').textContent='▶ Run demo';$('run-status').innerHTML='<span class="dot amber"></span> Demo interrupted';renderInspector();}if(e.target.id==='kernel-detail')openFeature('lifecycle');if(e.target.id==='history-detail')openFeature('history');if(e.target.id==='open-process')dialog('Process → notebook tab','<p>Clicking a runtime opens an attached notebook-like view without starting a duplicate process. Reconnecting a closed tab reattaches by runtime ID.</p><div class="mock-tabs"><span>signal-experiment.ipymb</span><span>api-service · live</span></div><div class="path-preview">runtime_id: demo-kernel-01<br>view_id: a new tab<br>process count: unchanged</div>');if(e.target.id==='inspect-contract')openFeature('contracts');});
$('add-intent').onclick=()=>openFeature('intent');$('welcome-account').onclick=()=>openFeature('auth');
function download(filename,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const anchor=document.createElement('a');anchor.href=url;anchor.download=filename;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast(filename+' downloaded.');}
function exportGraph(){
 const cellNodes=nodes.filter(n=>!n.kind.includes('trigger'));
 const cells=cellNodes.map(n=>n.kind==='markdown'?{cell_type:'markdown',id:n.id,source:n.text,metadata:{}}:{cell_type:'code',id:n.id,source:n.code,outputs:[],execution_count:null,metadata:{}});
 const graphNodes=nodes.map(n=>({id:n.id,kind:n.id==='start'?'start':n.id==='finish'?'finish':n.kind,...(!n.kind.includes('trigger')?{cell_index:cellNodes.indexOf(n)}:{})}));
 const graphEdges=edges.map(([source,target,kind,name],i)=>({id:'edge-'+(i+1),source,target,kind,...(name?{name}:{})}));
 const layoutNodes=Object.fromEntries(nodes.map(n=>[n.id,{x:positions[n.id][0],y:positions[n.id][1]}]));
 download('signal-experiment.ipymb',JSON.stringify({format:'mainaiger',schema_version:1,notebook:{nbformat:4,nbformat_minor:5,metadata:{mainaiger:{title:'Signal experiment',prototype:true}},cells},graph:{nodes:graphNodes,edges:graphEdges},layout:{nodes:layoutNodes,viewport:{x:state.pan.x,y:state.pan.y,zoom:state.zoom}}},null,2));
}
function exportPython(){download('signal_experiment.py','# MainAIger design example: deterministic single-process export.\n# Requires NumPy. No runtime state is embedded.\n\n'+['load','normalize','train','inspect','evaluate'].map(id=>{const n=nodes.find(n=>n.id===id);return'# %% '+n.title+'\n'+n.code;}).join('\n\n')+'\n','text/x-python');}
$('export-button').onclick=()=>dialog('Export this example','<p>A graph file stores code, connections, and layout. It does not preserve a live Python process.</p><button class="button primary" id="download-graph">Download .ipymb example</button> <button class="button" id="download-python">Export .py example</button><p>The .ipymb file uses the version 1 prototype schema supported by the included notebook bridge. The .py export is a runnable, single-process NumPy example; it cannot express arbitrary distributed graphs.</p>');
document.addEventListener('click',e=>{if(e.target.id==='download-graph')exportGraph();if(e.target.id==='download-python')exportPython();if(e.target.id==='add-alias'){state.alias=true;renderNodes();$('detail-dialog').close();switchView('lab');setTransform(100);defaultCanvasView();toast('A second visual Start control references the same trigger.');}});
document.querySelectorAll('[data-file]').forEach(el=>el.onclick=()=>{if(el.dataset.file.endsWith('.ipymb')){switchView('lab');return;}dialog(el.dataset.file,el.dataset.file==='data.csv'?'<p>File viewer example. The real file browser is scoped to the selected workspace.</p><pre>sample,signal\n0,0.000\n1,0.049\n2,0.098</pre>':'<p>This experiment demonstrates normalization, model estimation, and independent inspection of an input signal.</p>','FILE PREVIEW');});
document.querySelectorAll('[data-menu]').forEach(el=>el.onclick=()=>{const menu=el.dataset.menu;const bodies={File:'<p>Save a draft, open a graph, import .ipynb, export .ipymb, or export a supported .py execution plan.</p><button class="button" id="download-graph">Download graph example</button> <button class="button" id="download-python">Download Python</button>',Edit:'<p>Undo/redo, cut/copy/paste cells, duplicate visual trigger aliases, and edit cell contracts. Runtime actions are separate from document edits.</p>',View:'<p>Notebook and Graph are two views of the same cell identities. Variables, files, runtime monitor, trace, and minimap are dockable panels.</p>',Run:'<p>Run one cell, selected cells, prerequisites, or a subgraph. Validate required inputs before execution. A shared Python kernel runs one cell at a time.</p>',Kernel:'<p>Attach, launch, interrupt, restart, and shut down a kernel. Completing a workflow does not automatically destroy its namespace.</p>',Help:'<p>This browser prototype simulates execution. Drag graph nodes, pan the canvas, try a missing dependency, and download the example graph. No terminal command or Python code is executed.</p><p>Canvas: scroll to pan, Ctrl/⌘ + scroll to zoom, drag a header to move a graph node. Focus a node and press Enter to select it.</p>'};dialog(menu,bodies[menu],'JUPYTER-FAMILIAR MENU');});
