function renderAtlas(){const groups=['All','Setup','Canvas','Execution','Processes','Files'];$('atlas-filters').innerHTML=groups.map(g=>`<button class="${state.filter===g?'active':''}" data-filter="${g}">${g}${g==='All'?' · '+features.length:''}</button>`).join('');$('atlas-grid').innerHTML=features.filter(f=>state.filter==='All'||f.group===state.filter).map(f=>`<button class="atlas-card" data-feature="${f.id}"><div class="atlas-preview">${mock[f.preview]}</div><div class="atlas-description"><small>${f.group}</small><h2>${f.title} <span style="float:right;color:#a7bbae">↗</span></h2><p>${f.summary}</p></div></button>`).join('');}
function openFeature(id){const f=features.find(f=>f.id===id);if(!f)return;dialog(f.title,`<div class="atlas-preview">${mock[f.preview]}</div><p>${f.summary}</p><h3>GUI elements</h3><p>${f.controls}</p><h3>Behavior & boundary</h3><p>${f.behavior}</p><h3>First implementation</h3><p>${f.first}</p>${id==='alias'?'<button class="button primary" id="add-alias">Add an alias to the canvas</button>':''}`,f.group.toUpperCase()+' / INTERFACE SPECIFICATION');}
$('atlas-filters').onclick=e=>{const el=e.target.closest('[data-filter]');if(el){state.filter=el.dataset.filter;renderAtlas();}};$('atlas-grid').onclick=e=>{const el=e.target.closest('[data-feature]');if(el)openFeature(el.dataset.feature);};
window.addEventListener('resize',()=>{if(state.view==='lab'){drawEdges();defaultCanvasView();}});
renderSetup();renderNodes();renderInspector();renderAtlas();switchView(titles[location.hash.slice(1)]?location.hash.slice(1):'welcome');
